impl Specification {
    pub(super) fn add_eval_ir_bmem_trie(&mut self) -> Result<(), SpecError> {
        for (inductive, source, description) in decls() {
            if inductive {
                self.add_inductive(source, description)?;
            } else {
                self.add_recursive_def(source, description)?;
            }
        }
        Ok(())
    }
}

#[cfg(test)]
pub(super) fn test_source_rows() -> Vec<(&'static str, &'static str, &'static str)> {
    let rows = decls();
    assert_eq!(rows.len(), BMEM_TRIE_NAMES.len());
    BMEM_TRIE_NAMES
        .iter()
        .copied()
        .zip(rows)
        .map(|(name, (is_inductive, source, _description))| {
            (name, if is_inductive { "inductive" } else { "def" }, source)
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_bmem_trie_sources_are_ascii_balanced_and_named_in_order() {
        let ds = decls();
        assert_eq!(ds.len(), BMEM_TRIE_NAMES.len());
        for ((inductive, src, _), name) in ds.iter().zip(BMEM_TRIE_NAMES) {
            assert!(
                src.is_ascii() || *inductive,
                "{name}: spec sources stay ASCII"
            );
            assert_eq!(
                src.matches('(').count(),
                src.matches(')').count(),
                "{name}: unbalanced parentheses"
            );
            let head = if *inductive { "inductive" } else { "def" };
            assert!(src.starts_with(&format!("{head} {name} ")), "{name}");
        }
    }
}
